dashboard.definition:
{
    "visualizations": {
        "viz_threat": {
            "type": "splunk.custom",
            "options": {
                "type": "better_map",
                "name": "better_map",
                "tileProvider": "openfreemap-liberty",
                "pointRenderer": "markers",
                "pathColor": "#fb8072",
                "pathAnimated": true,
                "pathArrows": true,
                "markerColor": "#fdb462",
                "showTimeScrubber": "true",
                "trailWindowMs": "60000"
            },
            "dataSources": {
                "primary": "ds_threat"
            }
        }
    },
    "dataSources": {
        "ds_threat": {
            "type": "ds.search",
            "options": {
                "query": "| makeresults count=80 | streamstats c | eval pathId = \"attack-\" . c | eval origLat = 35 - random()%70 | eval origLon = 180 - random()%360 | eval dstLat = case(c%3=0, 38.89, c%3=1, 51.5, true(), 35.68) | eval dstLon = case(c%3=0, -77.04, c%3=1, -0.13, true(), 139.65) | eval _time = relative_time(now(), \"-30m\") + c * 20 | eval color = case(c%3=0, \"#fb8072\", c%3=1, \"#fdb462\", true(), \"#bebada\") | append [| makeresults count=80 | streamstats c | eval pathId = \"attack-\" . c | eval origLat = 35 - random()%70 | eval origLon = 180 - random()%360 | eval dstLat = case(c%3=0, 38.89, c%3=1, 51.5, true(), 35.68) | eval dstLon = case(c%3=0, -77.04, c%3=1, -0.13, true(), 139.65) | eval _time = relative_time(now(), \"-30m\") + c * 20 + 12 | eval color = case(c%3=0, \"#fb8072\", c%3=1, \"#fdb462\", true(), \"#bebada\") | eval lat = dstLat | eval lon = dstLon | fields _time pathId lat lon color] | eval lat = if(isnull(lat), origLat, lat) | eval lon = if(isnull(lon), origLon, lon) | fields _time pathId lat lon color"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": { "earliest": "-30m", "latest": "now" }
                }
            }
        }
    },
    "inputs": {},
    "layout": {
        "type": "absolute",
        "options": { "width": 1440, "height": 960, "backgroundColor": "#0b1a2d" },
        "structure": [
            { "item": "viz_threat", "type": "block", "position": { "x": 0, "y": 0, "w": 1440, "h": 960 } }
        ]
    }
}
